import json, random, subprocess, base64, sys
random.seed(777)

def sub(prog, cmd, data):
    p = subprocess.run(["python3", prog, cmd], input=data, capture_output=True)
    return p.returncode, p.stdout, p.stderr

IDS=["a","b"]; CIDS=["c1","c2"]; KEYS=["k1"]
FLOW=["10.0.0.1",1000,"10.0.0.2",80,"tcp"]
HOSTS=["1.2.3.4","::1","2001:db8::1","bad","fe80::1%z","01.1.1.1"]

def gen(t):
    r=random.random; pick=random.choice
    if r()<0.15: return {"op":"add","id":pick(IDS),"weight":random.randint(1,4)}
    if r()<0.10: return {"op":"ep","id":pick(IDS),"host":pick(HOSTS),"port":random.randint(0,70000)}
    if r()<0.10: return {"op":"fw","cid":pick(CIDS)}
    if r()<0.10: return {"op":"open","cid":pick(CIDS),"flow":FLOW,"now":t}
    if r()<0.08: return {"op":"close","cid":pick(CIDS),"now":t}
    if r()<0.05: return {"op":"remove","id":pick(IDS)}
    if r()<0.05: return {"op":"chash","vnodes":8}
    if r()<0.05: return {"op":"os","cap":2,"q":3,"ttl":10}
    if r()<0.08: return {"op":"oa","cid":pick(CIDS),"flow":FLOW,"c":"c","s":"s","key":"k","now":t}
    if r()<0.05: return {"op":"ot","now":t}
    if r()<0.06: return {"op":"fx","cid":pick(CIDS),"flow":FLOW,"key":"k","timeout":3,"now":t}
    if r()<0.06: return {"op":"fr","cid":pick(CIDS),"flow":FLOW,"key":"k","timeout":3,"max":2,"now":t}
    if r()<0.04: return {"op":"ts","ttl":5}
    if r()<0.04: return {"op":"tx","now":t}
    if r()<0.04: return {"op":"ds","id":pick(IDS),"t":3}
    if r()<0.04: return {"op":"dr","id":pick(IDS),"now":t}
    if r()<0.04: return {"op":"dg","id":pick(IDS),"now":t}
    if r()<0.05: return {"op":"ce"}
    return {"op":"get","cid":pick(CIDS)}

for trial in range(500):
    t=0; ops=[]
    for _ in range(random.randint(1,30)):
        t+=random.randint(0,3); ops.append(gen(t))
    raw=json.dumps({"ops":ops}).encode()
    c,out,err=sub("balancer.py","run",raw)
    # record/replay must reproduce byte-identically
    rc,rec,_=sub("balancer.py","record",raw)
    assert rc==0
    recj=json.loads(rec)
    assert recj["exit"]==c
    assert base64.b64decode(recj["stdout"])==out
    assert base64.b64decode(recj["stderr"])==err
    rc2,out2,err2=sub("balancer.py","replay",rec)
    assert (rc2,out2,err2)==(c,out,err),(trial,rc2,c)
    # fw consistency: for each successful fw in results, backend must match get
    if c==0:
        res=json.loads(out)["results"]
        # re-derive: run again with get after each fw? simpler: check key order
        for r in res:
            if r.get("op")=="fw":
                assert list(r.keys())==["op","cid","backend","host","port"],r
            if r.get("op")=="ce":
                cfg=r["config"]
                assert cfg["version"]==6
                for b in cfg["backends"]:
                    assert list(b.keys())==["id","weight","d","fail","success","circuit","drain","endpoint"]
                    if b["endpoint"] is not None:
                        assert list(b["endpoint"].keys())==["host","port"]
